CREATE TRIGGER maintenance_file_admission BEFORE INSERT ON asset_file_versions WHEN EXISTS(SELECT 1 FROM content_transitions WHERE maintenance_state<>'open' OR (local_site=target_site AND phase NOT IN ('target_owned','complete'))) BEGIN SELECT RAISE(ABORT,'content_transition_maintenance_admission'); END;
