CREATE TRIGGER maintenance_ai_claim BEFORE UPDATE OF lease_token ON music_ai_reviews WHEN NEW.lease_token IS NOT NULL AND NEW.lease_token IS NOT OLD.lease_token AND EXISTS(SELECT 1 FROM content_transitions WHERE maintenance_state<>'open' OR (local_site=target_site AND phase NOT IN ('target_owned','complete'))) BEGIN SELECT RAISE(ABORT,'content_transition_maintenance_admission'); END;
